import os
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class CartPage:
    """Page Object for the Shopping Cart Interface"""
    DROP_AREA = (By.CSS_SELECTOR, "[data-testid='drop-area']")
    PRODUCT_ITEM = (By.CSS_SELECTOR, "[data-testid^='product-item-']")

    def __init__(self, driver):
        self.driver = driver
        self.wait = WebDriverWait(driver, 10)

    def get_element_draggable_status(self, locator):
        element = self.wait.until(EC.presence_of_element_located(locator))
        return element.get_attribute("draggable") == "true"

# --- Behave Steps ---

@given('the webpage is loaded with a product list')
def step_given_webpage_loaded(context):
    file_path = f"file://{os.path.abspath('index.html')}"
    context.driver.get(file_path)
    context.cart_page = CartPage(context.driver)

@when('the user attempts to drag the non-draggable element with data-testid "drop-area"')
def step_when_attempt_drag_non_draggable(context):
    context.is_draggable = context.cart_page.get_element_draggable_status(CartPage.DROP_AREA)

@then('no drag event should be initiated')
def step_then_no_drag_event_initiated(context):
    assert context.is_draggable is False, "Drag event was incorrectly initiated for a non-draggable element."

@then('no product title should be captured')
def step_then_no_product_title_captured(context):
    # Verify that the drop area does not contain drag-related data attributes
    drop_area = context.driver.find_element(*CartPage.DROP_AREA)
    assert drop_area.get_attribute("data-dragged-title") is None, "Product title was captured unexpectedly."

@then('no product price should be captured')
def step_then_no_product_price_captured(context):
    drop_area = context.driver.find_element(*CartPage.DROP_AREA)
    assert drop_area.get_attribute("data-dragged-price") is None, "Product price was captured unexpectedly."

