        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='delete-note-button']"))
    )
    delete_button.click()
    time.sleep(1)

@then("the note is removed from the page")
def step_then_note_removed_from_page(context):
    notes = context.driver.find_elements(By.CSS_SELECTOR, ".note")
    assert len(notes) == 0, "Expected no notes on the page"

@then("localStorage does not contain \"Sample Note\"")
def step_then_localstorage_does_not_contain_sample_note(context):
    notes = context.driver.execute_script("return localStorage.getItem('notes');")
    assert "Sample Note" not in notes, "Expected 'Sample Note' not to be in localStorage"

def after_scenario(context, scenario):
    context.driver.quit()

