from playwright.sync_api import Page, expect
from behave import given, when, then

class NotesPage:
    def __init__(self, page: Page):
        self.page = page
        self.add_button = page.get_by_test_id("add-note-button")
        self.textarea = page.get_by_test_id("note-textarea")
        self.edit_button = page.get_by_test_id("edit-note-button")
        self.delete_button = page.get_by_test_id("delete-note-button")
        self.note_container = page.locator(".note")

    def navigate(self, url: str):
        self.page.goto(url)

@given("the Notes App page is loaded")
def step_given_notes_app_page_loaded(context):
    context.notes_page = NotesPage(context.page)
    context.notes_page.navigate("file://index.html")

@given('a note is created with the text "{text}"')
def step_given_note_created(context, text):
    context.notes_page.add_button.click()
    context.notes_page.textarea.fill(text)

@when("the user clicks the 'Delete' button with data-testid 'delete-note-button'")
def step_when_user_clicks_delete_button(context):
    context.notes_page.delete_button.click()

@then("the note is removed from the page")
def step_then_note_removed_from_page(context):
    expect(context.notes_page.note_container).to_have_count(0)

@then('localStorage does not contain "{text}"')
def step_then_localstorage_does_not_contain_sample_note(context, text):
    storage_content = context.page.evaluate("localStorage.getItem('notes')")
    assert text not in (storage_content or ""), f"Expected '{text}' not to be in localStorage, but found: {storage_content}"

