class MovieBookingPage:
    def __init__(self, driver):
        self.driver = driver
        self.wait = WebDriverWait(driver, 10)

    # Locators
    MOVIE_SELECT = (By.CSS_SELECTOR, "[data-testid='movie-select']")
    SELECTED_COUNT = (By.CSS_SELECTOR, "[data-testid='selected-count']")
    TOTAL_PRICE = (By.CSS_SELECTOR, "[data-testid='total-price']")

    def select_movie(self, test_id):
        self.wait.until(EC.element_to_be_clickable(self.MOVIE_SELECT)).click()
        self.driver.find_element(By.CSS_SELECTOR, f"[data-testid='{test_id}']").click()

    def click_seat(self, seat_id):
        self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, f"[data-testid='{seat_id}']"))).click()

    def get_selected_count(self):
        return self.wait.until(EC.visibility_of_element_located(self.SELECTED_COUNT)).text.strip()

    def get_total_price(self):
        return self.wait.until(EC.visibility_of_element_located(self.TOTAL_PRICE)).text.strip()

# Behave Steps
