    context.page.click_seat(seat_id)

@then('the selected seat count displayed with data-testid "selected-count" should be "{count}"')
def step_impl(context, count):
    assert context.page.get_selected_count() == count

@then('the total price displayed with data-testid "total-price" should be "${price}"')
def step_impl(context, price):
    assert context.page.get_total_price() == f"${price}"

