import os
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class DictionaryPage:
    SEARCH_INPUT = (By.CSS_SELECTOR, '[data-testid="search-input"]')
    SEARCH_BUTTON = (By.CSS_SELECTOR, '[data-testid="search-button"]')
    RESET_BUTTON = (By.CSS_SELECTOR, '[data-testid="reset-button"]')
    RESULT_CARD = (By.CSS_SELECTOR, '[data-testid="result-card"]')

    def __init__(self, driver):
        self.driver = driver
        self.wait = WebDriverWait(driver, 10)

    def search_for(self, word):
        input_field = self.wait.until(EC.visibility_of_element_located(self.SEARCH_INPUT))
        input_field.clear()
        input_field.send_keys(word)
        self.driver.find_element(*self.SEARCH_BUTTON).click()

    def reset(self):
        self.driver.find_element(*self.RESET_BUTTON).click()

    def is_result_card_visible(self):
        try:
            return self.driver.find_element(*self.RESULT_CARD).is_displayed()
        except:
            return False

# --- Behave Steps ---

@given('the user is on the Dictionary page')
def step_impl(context):
    context.page = DictionaryPage(context.driver)
    context.driver.get(f"file://{os.path.abspath('index.html')}")

@given('the search input field with data-testid "search-input" contains the text "example"')
def step_impl(context):
    context.page.search_for("example")

@given('the user clicks the search button with data-testid "search-button"')
def step_impl(context):
    # Already handled in search_for, but kept for step compatibility
    pass

@given('the result card with data-testid "result-card" is visible')
def step_impl(context):
    assert context.page.is_result_card_visible() is True

@when('the user clicks the \'Reset\' button with data-testid "reset-button"')
def step_impl(context):
    context.page.reset()

@then('the search input field with data-testid "search-input" should be empty')
def step_impl(context):
    input_val = context.driver.find_element(*DictionaryPage.SEARCH_INPUT).get_attribute('value')
    assert input_val == ""

@then('the result card with data-testid "result-card" should not be visible')
def step_impl(context):
    assert context.page.is_result_card_visible() is False
